import { useEffect, useState } from 'react'
import rawSnapshot from '../data/github-snapshot.json'

interface Snapshot {
  generatedAt: string
  user: string
  repos: {
    name: string; description: string; language: string | null; url: string; stars: number
    createdAt: string; pushedAt: string; commits: number; firstCommit: string | null; lastCommit: string | null
    months: Record<string, number>; recent: { date: string; message: string }[]
  }[]
  daily: Record<string, number>
}
/** Generated by scripts/build-github-snapshot.py from each public repo's git log. */
const snapshot = rawSnapshot as unknown as Snapshot

export interface RepoInfo {
  name: string
  description: string
  language: string | null
  url: string
  stars: number
  pushedAt: string
}
export interface CommitInfo { repo: string; date: string; message: string; url?: string }

export type Source = 'loading' | 'live' | 'snapshot'

const USER = snapshot.user
const CACHE_KEY = 'gh-live-v1'
const TTL = 10 * 60 * 1000
// Profile README repo and this site's own repo.
const EXCLUDE = new Set([USER, `${USER}.github.io`, `${USER.toLowerCase()}.github.io`])

const snapshotRepos: RepoInfo[] = snapshot.repos
  .filter((r) => !EXCLUDE.has(r.name))
  .map((r) => ({ name: r.name, description: r.description, language: r.language, url: r.url, stars: r.stars, pushedAt: r.pushedAt }))
  .sort((a, b) => b.pushedAt.localeCompare(a.pushedAt))

const snapshotCommits: CommitInfo[] = snapshot.repos
  .filter((r) => !EXCLUDE.has(r.name))
  .flatMap((r) => r.recent.map((c) => ({ repo: r.name, date: c.date, message: c.message, url: `${r.url}/commits` })))
  .sort((a, b) => b.date.localeCompare(a.date))

interface Live { at: number; repos: RepoInfo[]; commits: CommitInfo[] | null }

function readCache(): Live | null {
  try {
    const raw = sessionStorage.getItem(CACHE_KEY)
    if (!raw) return null
    const v = JSON.parse(raw) as Live
    return Date.now() - v.at < TTL ? v : null
  } catch { return null }
}

/**
 * Public, unauthenticated GitHub API (60 requests/hour per visitor IP). No token is used.
 * Falls back to the build-time snapshot when the API is unavailable or rate-limited.
 */
export function useGitHub() {
  const [state, setState] = useState<{ source: Source; repos: RepoInfo[]; commits: CommitInfo[]; commitsLive: boolean; fetchedAt?: number }>({
    source: 'loading', repos: snapshotRepos, commits: snapshotCommits, commitsLive: false,
  })

  useEffect(() => {
    const ctrl = new AbortController()
    const cached = readCache()
    if (cached) {
      setState({ source: 'live', repos: cached.repos, commits: cached.commits ?? snapshotCommits, commitsLive: !!cached.commits, fetchedAt: cached.at })
      return
    }
    const get = (u: string) => fetch(u, { signal: ctrl.signal, headers: { Accept: 'application/vnd.github+json' } })
      .then((r) => { if (!r.ok) throw new Error(String(r.status)); return r.json() })

    ;(async () => {
      try {
        const raw: any[] = await get(`https://api.github.com/users/${USER}/repos?sort=pushed&per_page=100&type=owner`)
        const repos: RepoInfo[] = raw
          .filter((r) => !r.fork && !r.private && r.size > 0 && !EXCLUDE.has(r.name))
          .map((r) => ({ name: r.name, description: r.description ?? '', language: r.language, url: r.html_url, stars: r.stargazers_count, pushedAt: r.pushed_at }))
        let commits: CommitInfo[] | null = null
        try {
          const ev: any[] = await get(`https://api.github.com/users/${USER}/events/public?per_page=50`)
          const list = ev
            .filter((e) => e.type === 'PushEvent' && Array.isArray(e.payload?.commits) && e.payload.commits.length)
            .flatMap((e) => e.payload.commits.map((c: any) => ({
              repo: String(e.repo.name).split('/')[1], date: String(e.created_at).slice(0, 10),
              message: String(c.message).split('\n')[0].slice(0, 120), url: `https://github.com/${e.repo.name}/commit/${c.sha}`,
            })))
            .filter((c: CommitInfo) => !EXCLUDE.has(c.repo))
          if (list.length) commits = list
        } catch { /* events are optional */ }
        const at = Date.now()
        try { sessionStorage.setItem(CACHE_KEY, JSON.stringify({ at, repos, commits })) } catch { /* storage may be blocked */ }
        setState({ source: 'live', repos, commits: commits ?? snapshotCommits, commitsLive: !!commits, fetchedAt: at })
      } catch (e) {
        if ((e as Error).name === 'AbortError') return
        setState((s) => ({ ...s, source: 'snapshot' }))
      }
    })()
    return () => ctrl.abort()
  }, [])

  return state
}

export const snapshotMeta = { generatedAt: snapshot.generatedAt, daily: snapshot.daily, repos: snapshot.repos }
